禁商用禁二传禁二改（也给我吃一口的话可以二改₍ᐢ.ˬ.ᐢ₎），无言退群的请不要用我的美化……
带符号💜的地方是自定义文字区域
气泡默认380px，太大太小可自行调换
想换图链的搜索关键词url */

/* ============================================================
   ★1. 气泡核心结构与封面设计
   ============================================================ */

/* 聊天气泡主体：定义了巨大的上内边距给封面图留位 */
body.bubblechat .mes,body.bubblechat .mes[is_user="true"],.mes{
     padding:10px!important;
     padding-top:200px!important;
     padding-bottom:40px!important;
     border-radius:0!important;
     border:1px solid #E5E4E8!important;
     box-shadow:6px 6px 0 rgba(44,42,48,.04)!important;
     max-width:380px!important;
     margin:40px auto 25px auto!important;
     position:relative;
     background-color:#FAFAFA!important;
     background-image:none!important;
     box-sizing:border-box!important;
     overflow:visible!important
}

/* 消息块宽度重置 */
.mes_block{
     width:100%!important;
     max-width:100%!important;
     padding:0!important;
     margin:0!important
}

/* 文本排版：两端对齐 */
.mes_text{
     padding:0!important;
     margin:0!important;
     text-align:justify!important;
     text-justify:inter-ideograph!important;
     line-height:1.8!important
}

/* 气泡顶部封面图 💜 */
.mes::before{
     content:''!important;
     position:absolute!important;
     top:15px!important;
     left:15px!important;
     right:15px!important;
     height:140px!important;
     background-image:url('https://i.postimg.cc/HLWvbXCG/IMG-0414.png')!important;
     background-size:cover!important;
     background-position:center 30%!important;
     filter:contrast(1.1) brightness(.9) sepia(.1) hue-rotate(-10deg)!important;
     z-index:1;
     border:1px solid #E5E4E8
}

/* 头像外框：类似相框的竖向容器 */
.mesAvatarWrapper{
     position:absolute!important;
     top:70px!important;
     left:25px!important;
     width:90px!important;
     height:115px!important;
     z-index:10!important;
     background:#FAFAFA!important;
     padding:5px!important;
     padding-bottom:30px!important;
     border:1px solid #D5D3D9!important;
     box-shadow:2px 4px 8px rgba(0,0,0,.08)!important;
     overflow:hidden!important;
     display:block!important
}

/* 头像图片缩放处理 */
.mesAvatarWrapper .avatar{
     width:80px!important;
     height:80px!important;
     position:relative!important;
     overflow:hidden!important;
     display:block!important;
     margin:0 auto!important
}

.mesAvatarWrapper .avatar img{
     object-fit:cover!important;
     width:100%!important;
     height:100%!important;
     filter:grayscale(.2) contrast(1.05)!important
}

/* 头像框侧边装饰文字 💜 */
.mesAvatarWrapper::before{
     content:"PRIVATE MANUSCRIPT"!important;
     position:absolute!important;
     left:4px!important;
     top:40px!important;
     transform:rotate(-90deg) translateY(-50%)!important;
     transform-origin:left center!important;
     font-size:7px!important;
     color:#9A95A5!important;
     letter-spacing:1px!important;
     white-space:nowrap!important;
     z-index:10
}

/* 头像框右下角印章 💜 */
.mesAvatarWrapper::after{
     content:"雾"!important;
     position:absolute!important;
     right:2px!important;
     bottom:2px!important;
     width:18px!important;
     height:18px!important;
     color:#777676!important;
     font-size:10px!important;
     line-height:16px!important;
     text-align:center!important;
     font-weight:900!important;
     z-index:10!important;
     background-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><filter id="r"><feTurbulence type="fractalNoise" baseFrequency="0.15" numOctaves="3"/><feDisplacementMap in="SourceGraphic" scale="8"/></filter><rect x="5" y="5" width="90" height="90" fill="none" stroke="%23777676" stroke-width="10" filter="url(%23r)"/></svg>')!important;
     background-size:contain!important;
     background-repeat:no-repeat!important;
     filter:opacity(.85)!important
}

/* 角色名称背景条 */
.mes .name_text{
     position:absolute!important;
     left:130px!important;
     top:165px!important;
     font-size:1.4em!important;
     font-weight:700!important;
     color:#454545!important;
     letter-spacing:2px!important;
     z-index:10;
     background:#FAFAFA!important;
     padding:2px 8px!important;
     border:1px solid #2C2A30!important;
     text-shadow:none!important
}

/* 名字上方的英文小字标 💜 */
.mes .name_text::after{
     content:"Even the pain falls mute."!important;
     display:block!important;
     position:absolute;left:0;
     top:-18px; 
     font-size:8px!important;
     letter-spacing:1px!important;
     color:#FAFAFA!important;
     background: #999999!important;
     padding:2px 4px!important;
     white-space:nowrap
}

/* 消息底部状态显示（ID/Token/时间） */
.mes .mesIDDisplay{
     position:absolute!important;
     bottom:0px!important;
     left:6px!important;
     background:0 0!important;
     color:#777676!important;
     font-size:7px!important;
     z-index:15!important
}

.mes .tokenCounterDisplay{
     position:absolute!important;
     bottom:9px!important;
     left:6px!important;
     background:0 0!important;
     color:#777676!important;
     font-size:7px!important;
     z-index:15!important
}

.mes .mes_timer{
     position:absolute!important;
     bottom:19px!important;
     left:6px!important;
     background:0 0!important;
     color:#777676!important;
     font-size:7px!important;
     z-index:15!important
}

/* 右侧日期标签 */
.mes .timestamp{
     position:absolute!important;
     right:25px!important;
     top:130px!important;
     background:#FAFAFA!important;
     color:#584F66!important;
     font-size:9px!important;
     padding:2px 6px!important;
     border:1px solid #999999!important;
     z-index:10!important;
     font-style:normal;
     border-top:1px solid #584F66;
     width:auto
}

/* ============================================================
   ★2. UI 全局深度重构
   ============================================================ */

/* 强制所有元素去圆角 */
*{
border-radius:0!important
}

/* 统一输入框与按钮样式 */
.text_pole,textarea,select,.menu_button,.character_select,.group_select,input[type="text"],input[type="number"]{
     background-color:#FAFAFA!important;
     border:1px solid #B5B2BB!important;
     color:#2C2A30!important;
     border-radius:0!important;
     box-shadow:2px 2px 0 rgba(44,42,48,.05)!important;
     transition:all .2s ease
}

.text_pole:focus,textarea:focus,select:focus{
     border-color:#584F66!important;
     box-shadow:2px 2px 0 rgba(88,79,102,.2)!important;
     outline:none!important
}

/* 菜单按钮 */
.menu_button{
     background-color:#F3F2F5!important;
     font-weight:700
}

.menu_button:hover{
     background-color:#E5E4E8!important;
     color:#1a1a1a!important
}

/* 侧边栏及抽屉列表项 */
.inline-drawer-toggle,.list-group-item,.drawer-content .list-group-item,#extensions_menu .inline-drawer-toggle{
     background:#FAFAFA!important;
     background-image:none!important;
     border:1px solid #B5B2BB!important;
     margin:6px 8px!important;
     box-shadow:2px 2px 0 rgba(88,79,102,.08)!important;
     color:#2C2A30!important;
     font-weight:700!important;
     padding:10px 15px!important;
     transition:all .2s ease!important
}

.inline-drawer-toggle:hover,.list-group-item:hover{
     background:#F3F2F5!important;
     border-color:#584F66!important;
     transform:translate(-1px,-1px);
     box-shadow:3px 3px 0 rgba(88,79,102,.2)!important;
     color:#1a1a1a!important
}

.inline-drawer-toggle i,.inline-drawer-toggle .fa-chevron-down,.inline-drawer-toggle .fa-chevron-right,.inline-drawer-icon{
     color:#584F66!important;
     text-shadow:none!important
}

/* 侧边栏标题栏 (H4) */
#right-nav h4,#left-nav h4,.inline-drawer-header h4,.standoutHeader,.drawer-content h4{
     background:#2C2A30!important;
     color:#FAFAFA!important;
     border:1px solid #2C2A30!important;
     padding:8px 12px!important;
     margin:15px 8px 10px 8px!important;
     letter-spacing:2px!important;
     text-transform:uppercase;
     font-size:14px!important;
     box-shadow:3px 3px 0 #D5D3D9!important;
     text-align:center!important;
     text-shadow:none!important
}

/* 消息内标题 (H1-H4) */
.mes_text h1,.mes_text h2,.mes_text h3,.mes_text h4{
     background:transparent!important;
     color:#2C2A30!important;
     border:none!important;
     border-bottom:1px solid #D5D3D9!important;
     box-shadow:none!important;
     margin:15px 0 10px 0!important;
     padding:0 0 5px 0!important;
     text-align:
     left!important
}

/* 提示管理器列表样式 */
#completion_prompt_manager_list{
