}

#completion_prompt_manager_list .completion_prompt_manager_prompt_name.text_muted,#completion_prompt_manager_list .completion_prompt_manager_prompt_name *,#completion_prompt_manager_list .text_muted,.completion_prompt_manager_prompt_name{
