}

/* 滑块 (Range) 美化 */
input[type="range"]{-webkit-appearance:none!important;appearance:none!important;background:#D5D3D9!important;height:3px!important;border:none!important;box-shadow:none!important;outline:none!important;filter:none!important;mix-blend-mode:normal!important;opacity:1!important;overflow:visible!important
}

input[type="range"]::-webkit-slider-thumb,input[type="range"]::-moz-range-thumb{-webkit-appearance:none!important;
     width:34px!important;
     height:24px!important;     background:url('https://i.postimg.cc/qvvHTjkY/IMG-0421.png')center/contain no-repeat!important;
     border:0!important;
     border-radius:0!important;
     filter:drop-shadow(1px 1px 0 rgba(44,42,48,.2))grayscale(.8)!important
}

/* 复选框 (Checkbox) 美化 */
input[type="checkbox"]{
     border-radius:0!important;
     -webkit-appearance:none;
     appearance:none;
     background:0 0!important;
     border:1px solid #B5B2BB!important;
     width:16px;
     height:16px;
     position:relative;
     vertical-align:middle;
     cursor:pointer;
     outline:none!important
}

input[type="checkbox"]:checked{
     border-color:#584F66!important;
     background:0 0!important
}

input[type="checkbox"]::before{
     content:none!important
}

input[type="checkbox"]:checked::after{
     content:''!important;
     position:absolute;
     left:50%;
     top:50%;
     transform:translate(-50%,-50%)!important;
     width:18px;
     height:18px;
background:url('https://i.postimg.cc/qvvHTjkY/IMG-0421.png')center/cover no-repeat!important;
     filter:contrast(1.2)!important
}

/* 隐藏滚动条 */
::-webkit-scrollbar{display:none}

/* 顶栏图标缩小及透明度处理 */
#top-bar{
     margin:0 auto;
     left:0;
     right:0;
     display:inline-block;
     height:24px;
     position:absolute;
     box-shadow:none;
     opacity:0;
     z-index:3005
}

.drawer-icon{
     transform:scale(.55);
     color:#4A4754
}

/* 发送表单容器 */
#send_form{
     display:flex;
     flex-wrap:wrap;
     align-items:center;
     width:94%!important;
     max-width:800px;
     margin:10px auto!important;
     background:#FAFAFA!important;
     border:1px solid #E5E4E8!important;
     border-radius:0!important;
