}

/* ============================================================
   ★ 思维链 (Reasoning) 隐藏开关版：印章即开关
   ============================================================ */

/* 1. 让思维链头部变成一个透明的、覆盖在印章上的点击层 */
.mes_reasoning_header {
  background: transparent !important;
  border: none !important;
  position: absolute !important;
  /* 这里的坐标要精准对齐头像框右下角的印章 */
  top: 162px !important;    
  left: 92px !important;
  width: 25px !important;
  height: 25px !important;
  z-index: 100 !important;
  cursor: pointer !important;
  padding: 0 !important;
  margin: 0 !important;
}

/* 2. 隐藏思维链原本的所有视觉元素，只留点击功能 */
.mes_reasoning_header::after,
.mes_reasoning_header_title,
.mes_reasoning_header_title::before,
.mes_reasoning_arrow {
  display: none !important;
}

/* 3. 展开后的内容区样式（建议稍微下移，不遮挡名字） */
.mes_reasoning_content {
  margin-top: 10px !important;
  padding: 10px !important;
  background: rgba(250, 250, 250, 0.8) !important;
  border: 1px dashed #D5D3D9 !important;
  font-size: 12px !important;
  color: #666 !important;
}

/* ============================================================
   ★3. Markdown 文本美学重构
   ============================================================ */

/* 加粗文本 */
.mes_text strong{
     color:#2C2A30!important;
     font-weight:900!important;
     background:none!important;
     text-shadow:1px 1px 0 rgba(255,255,255,.6),-1px -1px 0 rgba(88,79,102,.1)!important
}

/* 斜体文本装饰 */
/* 斜体文本装饰 - 蝴蝶移动到右上方 */
.mes_text em {
    position: relative !important;
    padding-right: 15px !important; 
    font-style: italic !important;
    color: #000 !important;
    display: inline-block !important;
}

.mes_text em::after {
    content: '' !important;
    position: absolute !important;
    right: 5px; 
    top: -8px; 
    width: 20px;
    height: 20px;
    background: url('https://i.postimg.cc/XYjL1PVX/IMG-0423.png') center/contain no-repeat !important;
    z-index: 1;
}

/* 引用美化 */
q {
    background: rgba(150, 145, 160, 0.1); 
    padding: 0em 0.3em;
    border-radius: 3px;
    box-decoration-break: clone;
