    background: transparent !important; /* 杀掉灰色背景 */
    background-color: transparent !important;
    border: none !important;            /* 杀掉边框 */
    box-shadow: none !important;         /* 杀掉那圈阴影 */
    outline: none !important;
    opacity: 1 !important;               /* 确保完全不透明 */
    padding: 0 !important;
    width: 25px !important;
    height: 25px !important;
}

/* 4. 蝴蝶图注入：强制彩色，关闭所有滤镜 */
.fa-pencil::before, .fa-pencil-alt::before,
.fa-ellipsis::before, .fa-ellipsis-h::before {
    content: "" !important;
    display: block !important;
    width: 28px !important;
    height: 28px !important;
    background: url('https://i.postimg.cc/76JvddYb/IMG-0419.png') no-repeat center/contain !important;

    /* 关键：强制关闭灰色滤镜和遮罩 */
    filter: none !important; 
    -webkit-filter: none !important;
    -webkit-mask-image: none !important;
    mask-image: none !important;
}

/* 5. 自动隐藏：杀掉中间那个点不动的灰色多余按钮 */
/* 如果还有别的点不动的，就在括号里继续加类名 */
.mes_buttons .mes_button:has(.fa-thumbtack),
.mes_buttons .mes_button:has(.fa-bookmark),
.mes_buttons .mes_button:has(.fa-copy),
.mes_buttons .mes_button:has(.fa-share-nodes) {
    display: none !important;
}

/* 如果你的浏览器不支持 :has，用下面这行通用的隐藏法 */
.mes_buttons .fa-thumbtack, .mes_buttons .fa-bookmark, .mes_buttons .fa-copy {
    display: none !important;
}

/* --- 剥离所有按钮及图标阴影 --- */
.mes_buttons .mes_button,
.mes_buttons .mes_button i,
.mes_buttons .mes_button i::before {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;      /* 核心：干掉外阴影 */
    text-shadow: none !important;     /* 核心：干掉图标文字阴影 */
    filter: none !important;          /* 核心：干掉滤镜生成的投影 */
    outline: none !important;
}

/* 修复最后一条消息间距 */
.mes.last_mes > *:has(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
    margin-bottom: 0 !important;
    padding-bottom: 0 !important;
}
